-- ============================================================
-- PATCH: convert identity columns from GENERATED ALWAYS to
-- GENERATED BY DEFAULT so seed.sql can insert explicit IDs.
-- Safe to run AFTER schema.sql. Idempotent.
-- ============================================================

ALTER TABLE IF EXISTS users           ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS addresses       ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS categories      ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS products        ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS product_images  ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS carts           ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS cart_items      ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS wishlist        ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS orders          ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS order_items     ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS payments        ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS shipments       ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS reviews         ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS coupons         ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS feedback        ALTER COLUMN id DROP IDENTITY IF EXISTS;
ALTER TABLE IF EXISTS custom_design_requests ALTER COLUMN id DROP IDENTITY IF EXISTS;

ALTER TABLE users           ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE addresses       ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE categories      ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE products        ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product_images  ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE carts           ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE cart_items      ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE wishlist        ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE orders          ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE order_items     ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE payments        ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE shipments       ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE reviews         ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE coupons         ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE feedback        ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE custom_design_requests ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
